// Cold-start stdio path. Answers initialize and tools/list from FAST_MANIFEST (generated by
// scripts/build-fast-manifest.mjs from the real server) without loading the MCP SDK or zod.
// Anything else hands the stream to the full server: takeFastTransport() returns this transport,
// which replays the answered initialize into the SDK (its reply is swallowed) so client
// capabilities still reach the server.
import { FAST_MANIFEST } from './fast-manifest.js'

const INIT_ID = '__gm_fast_init__'
const IDLE_LOAD_MS = 1000
// The full bundle is a separate module instance (see fast-entry.js), so the handed-over transport is shared on globalThis.
const SHARED = '__gmFastStdioTransport'

class FastStdioTransport {
    constructor(input, output, onNeedFull) {
        this.input = input
        this.output = output
        this.onNeedFull = onNeedFull
        this.onmessage = undefined
        this.onclose = undefined
        this.onerror = undefined
        this.buffer = ''
        this.pending = []
        this.attached = false
        this.initParams = null
        this.initializedSeen = false
        this.swallow = false
        this.idleTimer = null
    }

    // Loading the full server blocks the event loop for ~150 ms, so it waits until the client goes quiet
    // (the client's tools/list follows initialize at once). The idle load keeps the per-session side effects
    // (running-image record, bundle-drift watch) on the same schedule as a session that never hands off.
    armIdle() {
        clearTimeout(this.idleTimer)
        this.idleTimer = setTimeout(() => this.onNeedFull?.(), IDLE_LOAD_MS)
    }

    listen() {
        this.input.on('data', (chunk) => {
            this.buffer += chunk.toString('utf8')
            let at
            while ((at = this.buffer.indexOf('\n')) !== -1) {
                const line = this.buffer.slice(0, at).replace(/\r$/, '')
                this.buffer = this.buffer.slice(at + 1)
                if (line.trim() !== '') this.receive(line)
            }
        })
    }

    write(message) {
        this.output.write(JSON.stringify(message) + '\n')
    }

    receive(line) {
        if (this.attached) return this.deliverRaw(line)
        let message
        try { message = JSON.parse(line) } catch { return this.handOff(line) }
        if (message.method === 'initialize' && this.initParams === null && message.params?.protocolVersion === FAST_MANIFEST.protocolVersion) {
            this.initParams = message.params
            this.write({ jsonrpc: '2.0', id: message.id, result: FAST_MANIFEST.initialize })
            this.armIdle()
            return
        }
        if (message.method === 'notifications/initialized' && this.initParams !== null) {
            this.initializedSeen = true
            return
        }
        if (message.method === 'tools/list' && this.initParams !== null && message.params?.cursor === undefined) {
            this.write({ jsonrpc: '2.0', id: message.id, result: FAST_MANIFEST.tools })
            this.armIdle()
            return
        }
        this.handOff(line)
    }

    handOff(line) {
        this.pending.push(line)
        clearTimeout(this.idleTimer)
        this.onNeedFull?.()
    }

    deliverRaw(line) {
        let message
        try { message = JSON.parse(line) } catch (error) { return this.onerror?.(error) }
        this.onmessage?.(message)
    }

    start() {
        this.attached = true
        clearTimeout(this.idleTimer)
        if (this.initParams !== null) {
            this.swallow = true
            this.onmessage?.({ jsonrpc: '2.0', id: INIT_ID, method: 'initialize', params: this.initParams })
            if (this.initializedSeen) this.onmessage?.({ jsonrpc: '2.0', method: 'notifications/initialized' })
        }
        const pending = this.pending
        this.pending = []
        for (const line of pending) this.deliverRaw(line)
        return Promise.resolve()
    }

    send(message) {
        if (this.swallow && message.id === INIT_ID && ('result' in message || 'error' in message)) {
            this.swallow = false
            return Promise.resolve()
        }
        this.write(message)
        return Promise.resolve()
    }

    close() {
        this.input.removeAllListeners?.('data')
        this.onclose?.()
        return Promise.resolve()
    }
}

// Starts the cold path when the process was launched with no arguments. Returns false when the full CLI must run first.
// No environment variable selects a transport: HTTP runs only when --http is typed (index.js wantsHttpTransport).
export function startFastStdio({ onNeedFull }) {
    if (process.argv.length > 2) return false
    const transport = new FastStdioTransport(process.stdin, process.stdout, onNeedFull)
    transport.listen()
    globalThis[SHARED] = transport
    return true
}

export function takeFastTransport() {
    const transport = globalThis[SHARED] ?? null
    globalThis[SHARED] = null
    return transport
}
